#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Bilnov M1 — Systeme de commentaires unifies (ADDITIF, non destructif). Ajoute modeles Comment/CommentLocation/... + enums + back-relations User/Project + lib commentWorkflow (teste) + helper + 6 routes API. Ne touche PAS CadAnnotation. Migration prisma db push additive. A appliquer apres la suite L2."""
import base64, json, os, sys, subprocess
FILES={"src/lib/commentWorkflow.ts": "", "src/lib/__tests__/commentWorkflow.test.ts": "", "src/lib/comments.ts": "", "src/app/api/projects/[id]/comments/route.ts": "", "src/app/api/comments/[cid]/route.ts": "", "src/app/api/comments/[cid]/status/route.ts": "", "src/app/api/comments/[cid]/messages/route.ts": "", "src/app/api/comments/[cid]/assignees/route.ts": "", "src/app/api/comments/[cid]/locations/route.ts": ""}
APPENDS=[["prisma/schema.prisma", "bW9kZWwgQ29tbWVudCB7", ""]]
EDITS=[["prisma/schema.prisma", "user-backrel", "Y29tbWVudHNDcmVhdGVkICBDb21tZW50W10=", "ICBAQG1hcCgidXNlcnMiKQ==", "ICBjb21tZW50c0NyZWF0ZWQgIENvbW1lbnRbXSAgICAgICAgQHJlbGF0aW9uKCJDb21tZW50QXV0aG9yIikKICBjb21tZW50TWVzc2FnZXMgIENvbW1lbnRNZXNzYWdlW10gQHJlbGF0aW9uKCJDb21tZW50TWVzc2FnZUF1dGhvciIpCiAgQEBtYXAoInVzZXJzIik="], ["prisma/schema.prisma", "project-backrel", "Y29tbWVudHMgICAgIENvbW1lbnRbXQ==", "ICBAQG1hcCgicHJvamVjdHMiKQ==", "ICBjb21tZW50cyAgICAgQ29tbWVudFtdCiAgQEBtYXAoInByb2plY3RzIik="]]
def d(s): return base64.b64decode(s).decode('utf-8')
def parse(argv):
    root,build='.',True; i=0
    while i<len(argv):
        if argv[i]=='--root': root=argv[i+1]; i+=2; continue
        if argv[i]=='--no-build': build=False
        i+=1
    return root,build
def write_files(root):
    for rel,enc in FILES.items():
        p=os.path.join(root,rel); os.makedirs(os.path.dirname(p),exist_ok=True); c=d(enc)
        if os.path.exists(p) and open(p,encoding='utf-8').read()==c: print("  = ",rel)
        else: open(p,'w',encoding='utf-8').write(c); print("  + ",rel)
def appends(root):
    for f,menc,cenc in APPENDS:
        p=os.path.join(root,f); src=open(p,encoding='utf-8').read(); m=d(menc)
        if m in src: print("  = append déjà présent:",f)
        else: open(p,'a',encoding='utf-8').write("\n"+d(cenc)); print("  + append:",f)
def patch(root):
    cache={}; ap=sk=0
    for f,name,dm,o,nw in EDITS:
        p=os.path.join(root,f)
        if not os.path.exists(p): print("!! introuvable:",f); sys.exit(1)
        src=cache.get(p) or open(p,encoding='utf-8').read(); marker,old,new=d(dm),d(o),d(nw)
        if marker in src: print("  = déjà",name); cache[p]=src; sk+=1; continue
        if old not in src: print("!! ANCRE KO:",name,"@",f); sys.exit(2)
        src=src.replace(old,new,1); cache[p]=src; ap+=1; print("  ~ patché",name)
    for p,src in cache.items(): open(p,'w',encoding='utf-8').write(src)
    print("  ->",ap,"patché(s),",sk,"déjà.")
def run(cmd,root):
    print("\n$"," ".join(cmd)); r=subprocess.run(cmd,cwd=root)
    if r.returncode: print("!! échec (rc=%d) — rien poussé."%r.returncode); sys.exit(r.returncode)
def main():
    root,build=parse(sys.argv[1:])
    print("== Bilnov M1 (commentaires unifies) =="); print("[1] fichiers"); write_files(root)
    print("[2] schéma (append additif)"); appends(root)
    print("[3] back-relations"); patch(root)
    print("[4] prisma + tests"+(" + build" if build else ""))
    if build: run(["npx","prisma","generate"],root); run(["npx","prisma","db","push"],root)
    run(["npm","install"],root); run(["npm","run","test"],root)
    if build: run(["npm","run","build"],root)
    print("\nOK. Bilnov M1 (commentaires unifies) appliqué%s. Aucun git push."%(" (migration+tests+build OK)" if build else " (tests OK)"))
if __name__=='__main__': main()
